import{_ as t,o,c as a,ag as s}from"./chunks/framework.2cFhd8Ux.js";const m=JSON.parse('{"title":"Due-Date Quizzes","description":"","frontmatter":{"source":"assessment/quizzes.md"},"headers":[],"relativePath":"assessment/quizzes.md","filePath":"assessment/quizzes.md"}'),n={name:"assessment/quizzes.md"};function r(i,e,d,h,u,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="due-date-quizzes" tabindex="-1">Due-Date Quizzes <a class="header-anchor" href="#due-date-quizzes" aria-label="Permalink to &quot;Due-Date Quizzes&quot;">​</a></h1><blockquote><p>Seven minutes, no AI, at the start of the Seminar on the day an assignment is due, about that assignment. If you did the work and understood what your agent did, it&#39;s easy. If the agent did the work and you didn&#39;t read it, it isn&#39;t.</p></blockquote><p>The practice comes from UT Austin&#39;s CS 378, where &quot;each homework due date opens with a 7-minute individual quiz on that homework&quot;, AI-free, with &quot;only a single browser tab open&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>). It answers a question the rest of the grading can&#39;t: did you understand the work you just submitted, while it is fresh?</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>The first 7 minutes of the Seminar, on the day an assignment is due. Assignments are due before next week&#39;s Seminar, so the week N Seminar&#39;s quiz is about the week N−1 assignment</td></tr><tr><td><strong>Which weeks</strong></td><td><strong>Weeks 2–14:</strong> 13 quizzes. None in week 1 (nothing is due yet), none in week 15 and none in week 16</td></tr><tr><td><strong>Length</strong></td><td>7 minutes, 3–4 short questions</td></tr><tr><td><strong>AI use</strong></td><td>🔴 AI off</td></tr><tr><td><strong>Weight</strong></td><td>10% for CS [4xxx], 5% for CS [5xxx]; lowest two dropped</td></tr><tr><td><strong>Where</strong></td><td>On Canvas in the Seminar room, or on paper</td></tr></tbody></table><p><strong>Why there is no quiz in week 15.</strong> University Regulation H-1-a says: &quot;No quizzes or exams may be given in lecture-recitation periods during the week before finals week.&quot; Week 15 is that week. Week 14&#39;s quiz, on the week 13 assignment, is the last one.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Individual and closed.</strong> Only the Canvas quiz tab is open: no editor, no terminal, no other tabs, no AI, no phone. Or take it on paper. You won&#39;t need anything else: the questions are about work you&#39;ve just done.</li><li><strong>On time.</strong> The quiz opens when the Seminar starts and closes 7 minutes later. If you arrive late, you get the time that&#39;s left. Extra-time accommodations are <a href="#accommodations">below</a>.</li><li><strong>Same questions for everyone</strong> in the section, written so that someone who did the assignment can answer from memory and understanding, not from looking things up.</li><li><strong>The answers</strong> are discussed right after the quiz or posted on Canvas the same day.</li></ul><h2 id="what-the-questions-ask" tabindex="-1">What the questions ask <a class="header-anchor" href="#what-the-questions-ask" aria-label="Permalink to &quot;What the questions ask&quot;">​</a></h2><p>Every question is about the assignment that was just due. There are four kinds:</p><table tabindex="0"><thead><tr><th>Kind</th><th>What it checks</th><th>Example</th></tr></thead><tbody><tr><td><strong>What did you do?</strong></td><td>That you know what is in your own submission</td><td>&quot;Your <code>mini-agent</code> blocks paths outside the workspace. In one sentence, how does your check work, and what does it do with a symlink?&quot;</td></tr><tr><td><strong>Why that way?</strong></td><td>That the decisions were yours, or that you understood them</td><td>&quot;In your <code>AGENTS.md</code> A/B test, what was your criterion for &#39;the agent followed the file&#39;? Why that one?&quot;</td></tr><tr><td><strong>What would happen if…?</strong></td><td>That you can predict behavior</td><td>&quot;A booking runs 23:30–00:30 across the night the clocks go back. Which of your properties would exercise this, if any?&quot;</td></tr><tr><td><strong>Read this</strong></td><td>That you can interpret the kind of output you produced</td><td>&quot;A mutation report shows a surviving mutant that replaces <code>&gt;=</code> with <code>&gt;</code> in <code>capacityOk</code>. Name a test input that would kill it.&quot;</td></tr></tbody></table><h3 id="examples-by-week" tabindex="-1">Examples by week <a class="header-anchor" href="#examples-by-week" aria-label="Permalink to &quot;Examples by week&quot;">​</a></h3><p>These are examples of the style; each week&#39;s actual quiz is written for that assignment.</p><ul><li><strong>Week 2</strong> (on the week 1 agent and trace dissection): &quot;Name the tool calls, in order, that your agent made in its first run.&quot; · &quot;Give one claim from your trace dissection that you marked inferred, and say how you would make it observed.&quot;</li><li><strong>Week 4</strong> (on the MCP server and the <code>AGENTS.md</code> A/B test): &quot;Write the JSON-RPC request a client sends to list your server&#39;s tools.&quot; · &quot;One of your two tasks: did the agent follow the file? What did you see that told you?&quot;</li><li><strong>Week 5</strong> (on the injection defenses and threat model): &quot;Your egress block allows which hosts? What happens to a request to any other host?&quot; · &quot;Which leg of the lethal trifecta does quarantined reading remove?&quot;</li><li><strong>Week 7</strong> (on the property suite): &quot;State one of your properties in words. Which seeded bug did it find, and what was the shrunk failing case?&quot;</li><li><strong>Week 10</strong> (on the review lab): &quot;Your review&#39;s precision and recall against the defect key were what? Which defect did you miss, and why?&quot;</li><li><strong>Week 13</strong> (on the eval report): &quot;Your judge agreed with your labels on most cases. What was its κ, and why is κ lower than percent agreement?&quot;</li></ul><h2 id="scoring" tabindex="-1">Scoring <a class="header-anchor" href="#scoring" aria-label="Permalink to &quot;Scoring&quot;">​</a></h2><p>Each quiz is scored out of <strong>10 points, for correctness</strong>, with partial credit for a right approach that doesn&#39;t finish. 13 quizzes are given; your lowest two are dropped, so 110 points count. &quot;I don&#39;t remember the exact name, but it&#39;s the function that checks the window before inserting&quot; earns most of the credit if it&#39;s right; a confident wrong answer earns none.</p><p>A quiz answer that contradicts your own submission (for example, describing a test that isn&#39;t in your repository) isn&#39;t an integrity matter by itself. It may lead to an &quot;explain it or redo it&quot; conversation (<a href="./#academic-integrity">how that works</a>).</p><h2 id="drops-and-make-ups" tabindex="-1">Drops and make-ups <a class="header-anchor" href="#drops-and-make-ups" aria-label="Permalink to &quot;Drops and make-ups&quot;">​</a></h2><ul><li><strong>Lowest two dropped.</strong> This covers an ordinary missed Seminar or a bad day.</li><li><strong>Recognized absences</strong> (Regulation M-1: official university activities, your own illness, family illness or care, other compelling circumstances; Regulation M-3: religious observance): the quiz is excused (removed from the total), or, if you prefer, made up in office hours within one week with a comparable set of questions.</li><li><strong>Other absences:</strong> the quiz scores zero, and the drops absorb it.</li><li><strong>Grace tokens don&#39;t apply.</strong> A token moves your assignment&#39;s deadline, but the quiz stays on the Seminar day; you take it on what you&#39;ve done so far.</li></ul><h2 id="accommodations" tabindex="-1">Accommodations <a class="header-anchor" href="#accommodations" aria-label="Permalink to &quot;Accommodations&quot;">​</a></h2><ul><li><strong>Extra time</strong> (CDAR letter, or ask): start the quiz in the 10 minutes before the Seminar, in the room or a nearby one, so you don&#39;t miss the concept talk; or finish it in a nearby room. Agree the arrangement in week 1.</li><li><strong>Screen readers and large print:</strong> the Canvas quiz is plain text with code in monospace blocks; a large-print paper version is available on request.</li><li><strong>Typed or written:</strong> either is fine.</li><li><strong>Online or remote for a week:</strong> take the quiz at the same time on Canvas with your camera on, or arrange a make-up.</li></ul>',21)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
